## Client-Side OpenAI (No Functions)
Ditch serverless proxy—call OpenAI API directly from browser using a proxy service or CORS workaround. Your static HTML/JS deploys to Firebase Hosting (Spark-friendly).

```html
<!DOCTYPE html>
<html>
<head><title>Coloured Sarcasm Bot</title></head>
<body>
  <div class="chatbox"></div>
  <textarea id="message" placeholder="Wassup bru?"></textarea>
  <button onclick="sendMessage()">Aweh</button>

  <script>
    const API_KEY = 'sk-your-key-here'; // Or use puter.js env vars
    const systemPrompt = `You are a sarcastic Cape Coloured ou from Cape Town, speaking lekker slang like "aweh", "sies", "bru", "ag shame", "moer". Answer casual but informative like ChatGPT.`;

    async function sendMessage() {
      const userMsg = document.getElementById('message').value;
      appendMessage(userMsg, 'user');

      try {
        const response = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${API_KEY}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            model: 'gpt-4o-mini',
            messages: [
              {role: 'system', content: systemPrompt},
              {role: 'user', content: userMsg}
            ],
            max_tokens: 500
          })
        });
        const data = await response.json();
        appendMessage(data.choices[0].message.content, 'bot');
      } catch(e) {
        appendMessage('Sies bru, API vrot today', 'bot');
      }
    }

    function appendMessage(text, sender) {
      const div = document.createElement('div');
      div.className = sender;
      div.textContent = text;
      document.querySelector('.chatbox').appendChild(div);
      document.getElementById('message').value = '';
    }
  </script>
</body>
</html>
```

